function Link({ href, children, className='', ...props }:{href:string;children:React.ReactNode;className?:string} & Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>,'href'|'className'|'children'>) {
  const safeHref = href === '/' || href.startsWith('/?page=') || href.startsWith('#') || href.startsWith('mailto:') || href.startsWith('http')
    ? href
    : href.startsWith('/') ? `/?page=${encodeURIComponent(href.slice(1))}` : href;
  return <a href={safeHref} className={className} {...props}>{children}</a>;
}
const workShowcaseHref=(slug:string)=>`/?page=work#showcase-project-${encodeURIComponent(slug)}`;
