function WorkCard({item,index=0}:{item:Work;index?:number}){
  const [tilt,setTilt]=useState({x:0,y:0,spotX:50,spotY:50})
  const localCover=`/xiaoyang-card-final-${(index%8)+1}.jpg`;
  const cover=item.cover_url&&!/images\.unsplash\.com/i.test(item.cover_url)?item.cover_url:localCover;
  return <Link href={workShowcaseHref(item.slug)} className="work-card" onPointerMove={event=>{if(event.pointerType==='touch')return;const rect=event.currentTarget.getBoundingClientRect();setTilt({x:((event.clientX-rect.left)/rect.width-.5)*3.5,y:((event.clientY-rect.top)/rect.height-.5)*-3.5,spotX:(event.clientX-rect.left)/rect.width*100,spotY:(event.clientY-rect.top)/rect.height*100})}} onPointerLeave={()=>setTilt({x:0,y:0,spotX:50,spotY:50})} style={{'--work-rotate-x':`${tilt.y}deg`,'--work-rotate-y':`${tilt.x}deg`,'--work-spot-x':`${tilt.spotX}%`,'--work-spot-y':`${tilt.spotY}%`} as React.CSSProperties}>
    <div className="work-image"><img src={cover} alt={item.title} onError={event=>{const image=event.currentTarget;if(image.dataset.fallback)return;image.dataset.fallback='1';image.src=localCover}}/><span>0{index+1}</span></div><div className="work-copy"><p className="eyebrow">{item.kicker}</p><h3>{item.title}</h3><p>{item.summary}</p><div><span className="result">{item.result}</span><ArrowRight/></div></div>
  </Link>
}

