type AvatarMessage={role:'user'|'assistant';content:string};
function friendlyAvatarError(error:unknown){
  const message=error instanceof Error?error.message.trim():'';
  if(/failed to fetch|networkerror|load failed|fetch failed|network request failed/i.test(message))return '网络连接失败，请检查网络后重试。';
  if(/timeout|timed out|abort/i.test(message))return '回答超时了，请稍后重试。';
  return message||'暂时无法回答，请稍后重试。';
}
function DigitalAvatar({config}:{config:AvatarSettings}){
  const [open,setOpen]=useState(false),[messages,setMessages]=useState<AvatarMessage[]>([{role:'assistant',content:config.welcome}]),[input,setInput]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
  const listRef=useRef<HTMLDivElement>(null),assistantMessageRef=useRef<HTMLParagraphElement>(null);
  useEffect(()=>{
    if(messages.length<=1||messages.at(-1)?.role!=='assistant')return;
    const reduceMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const list=listRef.current,message=assistantMessageRef.current;
    if(!list||!message)return;
    const top=list.scrollTop+message.getBoundingClientRect().top-list.getBoundingClientRect().top;
    list.scrollTo({top,behavior:reduceMotion?'auto':'smooth'});
  },[messages]);
  if(!config.enabled)return null;
  const send=async(raw:string,appendUser=true)=>{
    const question=raw.trim();
    if(!question||busy)return;
    const next=(appendUser?[...messages,{role:'user' as const,content:question}]:messages).slice(-10);
    setOpen(true);
    setMessages(next);
    if(appendUser)setInput('');
    setError('');
    setBusy(true);
    if(appendUser)window.requestAnimationFrame(()=>listRef.current?.scrollTo({top:listRef.current.scrollHeight,behavior:'smooth'}));
    try{
      const result=await api.chatAvatar(next);
      setMessages(value=>[...value,{role:'assistant' as const,content:result.reply}].slice(-10));
    }catch(e){
      setError(friendlyAvatarError(e));
    }finally{
      setBusy(false);
    }
  };
  const statusState=busy?'thinking':error?'retry':'ready';
  const statusLabel=busy?'THINKING':error?'RETRY':'READY';
  const retryQuestion=messages.filter(message=>message.role==='user').at(-1)?.content||'';
  return <section className={`digital-avatar ${open?'is-open':''}`} aria-label={config.name}><button className="digital-avatar-head" type="button" onClick={()=>setOpen(value=>!value)} aria-expanded={open}><span className="digital-avatar-orb"><Bot size={16}/></span><span><b>{config.name}</b><small>{config.subtitle}</small></span><span className={`digital-avatar-status is-${statusState}`} aria-live="polite"><i/> {statusLabel}</span>{open?<X size={16}/>:<MessageCircle size={17}/>}</button>{open?<div className="digital-avatar-panel"><div className="digital-avatar-messages" ref={listRef} aria-live="polite">{messages.map((message,index)=><p key={`${message.role}-${index}`} ref={message.role==='assistant'&&index===messages.length-1?assistantMessageRef:undefined} className={message.role}><span>{message.role==='assistant'?'分身':'你'}</span>{message.content}</p>)}{busy&&<p className="assistant thinking"><LoaderCircle className="spin" size={14}/> 正在整理回答…</p>}</div>{error&&<div className="digital-avatar-error" role="alert">{error}<button type="button" onClick={()=>void send(retryQuestion,false)} disabled={!retryQuestion}>重试</button></div>}<form className="digital-avatar-form" onSubmit={event=>{event.preventDefault();void send(input)}}><input value={input} onChange={event=>setInput(event.target.value)} placeholder={config.placeholder} aria-label="向数字分身提问" maxLength={2000} disabled={busy}/><button disabled={busy||!input.trim()} aria-label="发送"><Send size={16}/></button></form><div className="digital-avatar-actions"><div>{config.suggestions.slice(0,3).map(question=><button type="button" key={question} onClick={()=>void send(question)} disabled={busy}>{question}</button>)}</div><button type="button" className="digital-avatar-reset" onClick={()=>{setMessages([{role:'assistant',content:config.welcome}]);setError('')}} title="清空对话" aria-label="清空对话"><RotateCcw size={14}/></button></div></div>:<button className="digital-avatar-entry" type="button" onClick={()=>setOpen(true)}><span>{config.welcome}</span><b>开始对话 <ArrowRight size={14}/></b></button>}</section>;
}

function XiaoyangHeroComplete({data}:{data:SiteData}){const [open,setOpen]=useState(false);const [loading,setLoading]=useState(true);const [progress,setProgress]=useState(23);const [activeSection,setActiveSection]=useState('experience');const [pointer,setPointer]=useState({x:0,y:0});useEffect(()=>{const tick=window.setInterval(()=>setProgress(value=>value>=100?100:value+Math.max(2,Math.round((100-value)*.16))),80);const timer=window.setTimeout(()=>setLoading(false),1750);return()=>{window.clearInterval(tick);window.clearTimeout(timer)}},[]);useEffect(()=>{const ids=['experience','selected','strengths','contact'];const sections=ids.map(id=>document.getElementById(id)).filter((x):x is HTMLElement=>Boolean(x));if(!sections.length)return;const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting)setActiveSection(entry.target.id)}),{rootMargin:'-35% 0px -55%'});sections.forEach(section=>observer.observe(section));return()=>observer.disconnect()},[]);const cards=xiaoyangCardAssets.map((asset,i)=>({asset,work:data.works.length?data.works[i%data.works.length]:undefined}));return <section className="xiaoyang-hero" id="module" onPointerMove={e=>{const r=e.currentTarget.getBoundingClientRect();setPointer({x:(e.clientX-r.left)/r.width-.5,y:(e.clientY-r.top)/r.height-.5})}} style={{'--mx':`${pointer.x*12}px`,'--my':`${pointer.y*8}px`} as React.CSSProperties}><div className="xiaoyang-backdrop"/><div className="xiaoyang-night" aria-hidden="true"/><div className="xiaoyang-noise"/><div className={`xiaoyang-loader ${loading?'is-visible':''}`} aria-hidden={!loading}><small>LOADING PORTFOLIO</small><strong>{progress}%</strong><span/></div><nav className="xiaoyang-nav"><a className="xiaoyang-logo" href="/" aria-label="首页"><span className="xiaoyang-face">●</span><b>xiaoY</b></a><div className={`xiaoyang-navlinks ${open?'is-open':''}`}><a className={activeSection==='experience'?'is-active':''} href="#experience" onClick={()=>setOpen(false)}>工作经历</a><a className={activeSection==='selected'?'is-active':''} href="#selected" onClick={()=>setOpen(false)}>精选作品</a><a className={activeSection==='strengths'?'is-active':''} href="#strengths" onClick={()=>setOpen(false)}>个人优势</a><a className={`xiaoyang-contact ${activeSection==='contact'?'is-active':''}`} href="#contact" onClick={()=>setOpen(false)}>联系我</a></div><button className="xiaoyang-menu" onClick={()=>setOpen(!open)} aria-label={open?'关闭菜单':'打开菜单'} aria-expanded={open}>{open?<X size={20}/>:<Menu size={20}/>}</button></nav><div className="xiaoyang-intro"><p className="xiaoyang-kicker">视觉系统 · AI 工作流</p><h1>XIAOYANG<span>✦</span></h1><h2>PORTFOLIO <em>XiaoYang</em></h2><p className="xiaoyang-tagline">用视觉系统与 AI 工作流，让品牌内容更快、更准、更有辨识度。</p><DigitalAvatar config={data.avatar}/></div><div className="xiaoyang-strip-window" aria-label="精选作品预览"><div className="xiaoyang-strip">{[0,1].map(group=><div key={group} className="xiaoyang-strip-set" aria-hidden={group===1}>{cards.map(({asset,work},itemIndex)=>{const title=work?.title||`作品 ${itemIndex+1}`;return <a key={`${group}-${asset}`} href={work?.slug?workShowcaseHref(work.slug):'/?page=work'} className={`xiaoyang-card rhythm-${itemIndex%3}`} data-light-surface="" aria-label={`${String(itemIndex+1).padStart(2,'0')} ${title}`} tabIndex={group===1?-1:0}><SurfaceLight/><img src={asset} alt={group===0?title:''}/><span className="xiaoyang-card-index">{String(itemIndex+1).padStart(2,'0')}</span><span className="xiaoyang-card-copy"><b>{title}</b><small>{work?.kicker||'SELECTED WORK'}</small></span></a>})}</div>)}</div></div><div className="xiaoyang-scroll">SCROLL TO EXPLORE <ArrowDown size={13}/></div></section>}

function ScrollProgress(){useEffect(()=>{const update=()=>{const max=document.documentElement.scrollHeight-window.innerHeight;document.documentElement.style.setProperty('--xiao-scroll',String(max>0?window.scrollY/max:0))};update();addEventListener('scroll',update,{passive:true});addEventListener('resize',update);return()=>{removeEventListener('scroll',update);removeEventListener('resize',update)}},[]);return <div className="xiao-progress" aria-hidden="true"><span/></div>}
function SiteLoading(){const [progress,setProgress]=useState(23);useEffect(()=>{const timer=window.setInterval(()=>setProgress(value=>value>=100?100:value+Math.max(3,Math.round((100-value)*.18))),70);return()=>window.clearInterval(timer)},[]);return <main className="site-loading" role="status" aria-live="polite"><div className="site-loading-mark"><span className="xiaoyang-face">●</span><b>xiaoY</b></div><p>LOADING PORTFOLIO</p><strong>{progress}%</strong><span className="site-loading-line"/></main>}
function HashAnchorSync(){useEffect(()=>{const hash=window.location.hash;if(!hash)return;const target=document.getElementById(decodeURIComponent(hash.slice(1)));if(!target)return;const frame=window.requestAnimationFrame(()=>target.scrollIntoView({block:'start'}));return()=>window.cancelAnimationFrame(frame)},[]);return null}

function PdfCanvasViewer({url,onReady,onFailure}:{url:string;onReady:()=>void;onFailure:()=>void}){
  const containerRef=useRef<HTMLDivElement>(null);
  useEffect(()=>{
    const container=containerRef.current;
    if(!container)return;
    let cancelled=false;
    let documentTask:ReturnType<typeof getDocument>|undefined;
    let pdfDocument:PDFDocumentProxy|undefined;
    let renderTasks:RenderTask[]=[];
    let resizeTimer:number|undefined;
    const renderDocument=async()=>{
      if(!pdfDocument||cancelled)return;
      renderTasks.forEach(task=>task.cancel());
      renderTasks=[];
      container.replaceChildren();
      const availableWidth=Math.max(280,Math.min(container.clientWidth-48,980));
      const pixelRatio=Math.min(window.devicePixelRatio||1,2);
      for(let pageNumber=1;pageNumber<=pdfDocument.numPages;pageNumber+=1){
        if(cancelled)return;
        const page=await pdfDocument.getPage(pageNumber);
        const baseViewport=page.getViewport({scale:1});
        const cssScale=availableWidth/baseViewport.width;
        const viewport=page.getViewport({scale:cssScale*pixelRatio});
        const pageElement=document.createElement('figure');
        pageElement.className='resume-pdf-page';
        pageElement.setAttribute('aria-label',`简历第 ${pageNumber} 页，共 ${pdfDocument.numPages} 页`);
        const canvas=document.createElement('canvas');
        canvas.width=Math.ceil(viewport.width);
        canvas.height=Math.ceil(viewport.height);
        canvas.style.width=`${Math.round(viewport.width/pixelRatio)}px`;
        canvas.style.height=`${Math.round(viewport.height/pixelRatio)}px`;
        const context=canvas.getContext('2d',{alpha:false});
        if(!context)throw new Error('Canvas 2D context unavailable');
        pageElement.appendChild(canvas);
        container.appendChild(pageElement);
        const renderTask=page.render({canvas,canvasContext:context,viewport});
        renderTasks.push(renderTask);
        await renderTask.promise;
      }
      if(!cancelled)onReady();
    };
    const load=async()=>{
      try{
        documentTask=getDocument({url,withCredentials:false});
        pdfDocument=await documentTask.promise;
        await renderDocument();
      }catch(error){
        if(cancelled||error instanceof Error&&error.name==='RenderingCancelledException')return;
        onFailure();
      }
    };
    const observer=new ResizeObserver(()=>{
      if(!pdfDocument||cancelled)return;
      if(resizeTimer)window.clearTimeout(resizeTimer);
      resizeTimer=window.setTimeout(()=>{void renderDocument().catch(onFailure)},180);
    });
    observer.observe(container);
    void load();
    return()=>{
      cancelled=true;
      observer.disconnect();
      if(resizeTimer)window.clearTimeout(resizeTimer);
      renderTasks.forEach(task=>task.cancel());
      void documentTask?.destroy();
      void pdfDocument?.destroy();
    };
  },[url,onReady,onFailure]);
  return <div ref={containerRef} className="resume-pdf-pages" aria-label="简历 PDF 页面"/>;
}

function ResumePdfModule({resume}:{resume:ResumeData}){
  const sectionRef=useRef<HTMLElement>(null);
  const [visible,setVisible]=useState(false);
  const [pdfState,setPdfState]=useState<'checking'|'waiting'|'rendering'|'ready'>('checking');
  const [reloadToken,setReloadToken]=useState(0);
  const retryTimer=useRef<number|undefined>(undefined);
  useEffect(()=>{
    const element=sectionRef.current;
    if(!element)return;
    if(window.matchMedia('(prefers-reduced-motion: reduce)').matches){setVisible(true);return;}
    const observer=new IntersectionObserver(([entry])=>{
      if(entry.isIntersecting){setVisible(true);observer.disconnect();}
    },{threshold:.12,rootMargin:'0px 0px -7%'});
    observer.observe(element);
    return()=>observer.disconnect();
  },[]);
  if(!resume.pdf_enabled)return null;
  const url=resume.pdf_url.trim();
  const fileName=resume.pdf_file_name.trim()||url.split('/').pop()?.split('?')[0]||'Resume.pdf';
  const viewerBase=url.split('#')[0];
  const viewerUrl=url?`${viewerBase}${viewerBase.includes('?')?'&':'?'}pdfjs=resume-v1&resumeLoad=${reloadToken}`:'';
  const scheduleRetry=useCallback(()=>{
    setPdfState('waiting');
    if(retryTimer.current)window.clearTimeout(retryTimer.current);
    retryTimer.current=window.setTimeout(()=>{
      setPdfState('checking');
      setReloadToken(value=>value+1);
    },2500);
  },[]);
  useEffect(()=>()=>{if(retryTimer.current)window.clearTimeout(retryTimer.current)},[]);
  useEffect(()=>{
    if(!viewerBase){setPdfState('checking');return;}
    let target:URL;
    try{target=new URL(viewerBase,window.location.href)}catch{setPdfState('waiting');return;}
    if(target.origin!==window.location.origin){setPdfState('ready');return;}
    let cancelled=false;
    let retryTimer:number|undefined;
    setPdfState('checking');
    const probePdf=async()=>{
      try{
        const response=await fetch(target.href,{method:'HEAD',cache:'no-store'});
        if(!response.ok)throw new Error(`PDF unavailable: ${response.status}`);
        if(!cancelled)setPdfState('rendering');
      }catch{
        if(cancelled)return;
        scheduleRetry();
      }
    };
    void probePdf();
    return()=>{cancelled=true};
  },[viewerBase,reloadToken,scheduleRetry]);
  const reloadPdf=useCallback(()=>{
    if(retryTimer.current)window.clearTimeout(retryTimer.current);
    setPdfState('checking');
    setReloadToken(value=>value+1);
  },[]);
  const markReady=useCallback(()=>setPdfState('ready'),[]);
  return <section ref={sectionRef} id="resume-pdf" className={`resume-pdf-section ${visible?'is-visible':''}`}><div className="resume-pdf-head"><div><p className="eyebrow">{resume.pdf_kicker||'完整简历'}</p><h2 className="section-display">{resume.pdf_title||'RESUME'}</h2></div><p>{resume.pdf_description}</p></div><div className="resume-pdf-window"><div className="resume-pdf-toolbar"><div className="resume-window-dots" aria-hidden="true"><i/><i/><i/></div><div className="resume-file-name"><FileText size={24}/><span>{fileName}</span></div><div className="resume-pdf-actions">{url&&<button type="button" className="resume-pdf-reload" onClick={reloadPdf} aria-label="重新加载简历 PDF"><RefreshCw size={17}/><span>重载</span></button>}{url&&resume.pdf_show_open&&<a href={url} target="_blank" rel="noreferrer" aria-label="在新窗口打开简历"><ExternalLink size={17}/><span>新窗口</span></a>}{url&&resume.pdf_show_download&&<a href={url} download={fileName} aria-label="下载简历 PDF"><Download size={17}/><span>下载</span></a>}</div></div>{url?<div className="resume-pdf-frame-wrap">{(pdfState==='rendering'||pdfState==='ready')&&<PdfCanvasViewer key={viewerUrl} url={viewerUrl} onReady={markReady} onFailure={scheduleRetry}/>} {pdfState!=='ready'&&<div className="resume-pdf-recovery" role="status" aria-live="polite"><LoaderCircle className="spin"/><strong>{pdfState==='waiting'?'正在等待 PDF 服务恢复':pdfState==='rendering'?'正在绘制简历页面':'正在加载简历'}</strong><p>{pdfState==='waiting'?'服务恢复后会自动重新加载，也可以点击下方按钮立即重试。':pdfState==='rendering'?'文件已读取，正在生成清晰的页面预览。':'正在检查文件是否可用，请稍候。'}</p><button type="button" onClick={reloadPdf}><RefreshCw size={16}/> 立即重试</button></div>}</div>:<div className="resume-pdf-empty"><FileText/><strong>完整简历即将上线</strong><p>站长可在后台「简历管理」上传或选择 PDF。</p></div>}</div></section>
}

function PersonalExtensionGallery({works}:{works:Work[]}){
  const items=[...works.slice(0,1),{id:'pond-experiment',slug:'pond',title:'一方池塘',kicker:'INTERACTIVE / 交互实验',summary:'点一下，放一条鱼。让水光与游鱼陪你放空片刻。'},...works.slice(1,7)];
  const [pondOpen,setPondOpen]=useState(false);
  const closePond=useCallback(()=>setPondOpen(false),[]);
  const count=items.length;
  const viewportRef=useRef<HTMLDivElement>(null);
  const pointerRef=useRef<{id:number;x:number}|null>(null);
  const wheelRef=useRef({delta:0,timer:0});
  const draggedRef=useRef(false);
  const [step,setStep]=useState(461);
  const [index,setIndex]=useState(count+Math.min(1,count-1));
  const [dragOffset,setDragOffset]=useState(0);
  const [animated,setAnimated]=useState(true);
  const [reducedMotion,setReducedMotion]=useState(false);
  const modulo=(value:number)=>((value%count)+count)%count;
  const active=count?modulo(index):0;
  const loopItems=count?[0,1,2].flatMap(group=>items.map((item,itemIndex)=>({group,item,itemIndex,key:`${group}-${item.id}`}))):[];
  const selectItem=(target:number)=>{if(!count)return;setAnimated(true);setDragOffset(0);setIndex(current=>{let delta=target-modulo(current);if(delta>count/2)delta-=count;if(delta<-count/2)delta+=count;return current+delta})};
  const settle=(offset:number)=>{setAnimated(true);setDragOffset(0);if(Math.abs(offset)>=step*.18)setIndex(current=>current+(offset<0?1:-1))};

  useEffect(()=>{if(count)setIndex(count+Math.min(1,count-1))},[count]);
  useEffect(()=>{const media=matchMedia('(prefers-reduced-motion: reduce)');const sync=()=>setReducedMotion(media.matches);sync();media.addEventListener('change',sync);return()=>media.removeEventListener('change',sync)},[]);
  useEffect(()=>{if(!count||!reducedMotion)return;if(index>=count*2)setIndex(index-count);else if(index<count)setIndex(index+count)},[count,index,reducedMotion]);
  useEffect(()=>{const viewport=viewportRef.current;if(!viewport)return;const measure=()=>{const card=viewport.querySelector<HTMLElement>('.personal-extension-card');if(!card)return;const styles=getComputedStyle(viewport);setStep(card.offsetWidth+(Number.parseFloat(styles.getPropertyValue('--extension-gap'))||12))};measure();const observer=new ResizeObserver(measure);observer.observe(viewport);return()=>observer.disconnect()},[count]);
  useEffect(()=>{if(!count)return;const syncHash=()=>{const match=decodeURIComponent(location.hash).match(/^#extension-(.+)$/);if(!match)return;const target=items.findIndex(item=>item.slug===match[1]);if(target>=0)selectItem(target)};syncHash();addEventListener('hashchange',syncHash);return()=>removeEventListener('hashchange',syncHash)},[count]);
  useEffect(()=>()=>{if(wheelRef.current.timer)window.clearTimeout(wheelRef.current.timer)},[]);
  if(!count)return null;

  return <section id="personal-extension" className="personal-extension" aria-labelledby="personal-extension-title">
    <div className="personal-extension-head"><div><p className="eyebrow">MORE PRACTICE / 个人延伸</p><h2 id="personal-extension-title" className="section-display">个人延伸</h2><p className="extension-subtitle">把兴趣变成可落地的探索</p><small className="extension-english">EXPLORATION BEYOND WORK</small></div><div className="extension-intro"><div className="extension-counter"><b>{String(active+1).padStart(2,'0')}</b><span>/ {String(count).padStart(2,'0')}</span></div><p>在真实项目与产品 Demo 之外，我持续整理调研、界面、技术实验与空间观察，让分析、视觉表达和技术理解相互连接，探索 AI 在工作与生活中的更多可能。</p><div className="extension-navigation"><div className="personal-extension-rail">{items.map((item,itemIndex)=><button key={item.id} type="button" className={itemIndex===active?'is-active':''} onClick={()=>selectItem(itemIndex)} aria-label={`查看第 ${itemIndex+1} 项：${item.title}`} aria-pressed={itemIndex===active}/>)}</div><button className="extension-previous" type="button" aria-label="个人延伸：上一项" onClick={()=>selectItem(modulo(active-1))}><ArrowLeft size={17}/></button><button className="extension-next" type="button" aria-label="个人延伸：下一项" onClick={()=>selectItem(modulo(active+1))}><ArrowRight size={17}/></button></div></div></div>
    <div ref={viewportRef} className="personal-extension-viewport" onWheel={event=>{if(Math.abs(event.deltaX)<=Math.abs(event.deltaY))return;event.preventDefault();setAnimated(false);wheelRef.current.delta+=event.deltaX;setDragOffset(Math.max(-step,Math.min(step,-wheelRef.current.delta)));if(wheelRef.current.timer)window.clearTimeout(wheelRef.current.timer);wheelRef.current.timer=window.setTimeout(()=>{const delta=wheelRef.current.delta;wheelRef.current.delta=0;wheelRef.current.timer=0;settle(-delta)},140)}} onPointerDown={event=>{if(event.button!==0)return;pointerRef.current={id:event.pointerId,x:event.clientX};draggedRef.current=false;setAnimated(false)}} onPointerMove={event=>{const pointer=pointerRef.current;if(!pointer||pointer.id!==event.pointerId)return;const offset=Math.max(-step,Math.min(step,event.clientX-pointer.x));if(Math.abs(offset)>5){draggedRef.current=true;event.currentTarget.setPointerCapture(event.pointerId)}setDragOffset(offset)}} onPointerUp={event=>{const pointer=pointerRef.current;if(!pointer||pointer.id!==event.pointerId)return;pointerRef.current=null;settle(event.clientX-pointer.x)}} onPointerCancel={()=>{pointerRef.current=null;settle(0)}} onClickCapture={event=>{if(draggedRef.current){event.preventDefault();event.stopPropagation();draggedRef.current=false}}}>
<div className="personal-extension-track" data-index={index} style={{transform:`translate3d(${-(index*step)+dragOffset}px,0,0)`,transition:animated&&!reducedMotion?'transform 500ms ease-out':'none'}} onTransitionEnd={event=>{if(event.target!==event.currentTarget)return;if(index>=count*2||index<count){setAnimated(false);setIndex(current=>current>=count*2?current-count:current+count);requestAnimationFrame(()=>requestAnimationFrame(()=>setAnimated(true)))}}}>{loopItems.map(({group,item,itemIndex,key})=><Link key={key} id={group===1?`extension-${item.slug}`:undefined} href={item.id==='pond-experiment'?new URL('/pond/index.html',location.origin).href:workShowcaseHref(item.slug)} onClick={event=>{if(item.id==='pond-experiment'){event.preventDefault();setPondOpen(true)}}} data-light-surface="" className={`personal-extension-card ${itemIndex===active?'is-active':''}`} aria-hidden={group!==1} tabIndex={group===1?0:-1} draggable={false}><SurfaceLight/><div className="personal-extension-media"><img src={item.id==='pond-experiment'?'/pond/cover.svg':`/xiaoyang-card-final-${itemIndex>1?itemIndex:itemIndex+1}.jpg`} alt={group===1?item.title:''} draggable={false}/><span>{String(itemIndex+1).padStart(2,'0')}</span></div><div className="personal-extension-copy"><p>{item.kicker}</p><h3>{item.title}</h3><span>{item.summary}</span><i className="extension-card-arrow" aria-hidden="true"><ArrowRight size={16}/></i></div></Link>)}</div>
    </div>
    <div className="extension-footer"><span>LIFELONG EXPLORATION</span><p>更多实践 <i>/</i> 更大视野 <i>/</i> 更好的可能</p></div>
    {pondOpen&&<PondDialog onClose={closePond}/>}
  </section>
}

function Home({data}:{data:SiteData}){const [activeStrength,setActiveStrength]=useState(3);useEffect(()=>{const timer=window.setInterval(()=>setActiveStrength(value=>(value+1)%4),4200);return()=>window.clearInterval(timer)},[]);return <main className="home-cyber"><HashAnchorSync/><ScrollProgress/>
  <XiaoyangHeroComplete data={data}/>
  <section id="experience" className="proof"><div className="experience-layout"><div className="experience-portrait"><img src="/xiaoyang-portrait-reference.jpg" alt="XiaoYang 头像"/></div><div className="experience-copy"><p className="eyebrow">个人经历</p><h2 className="section-display">Hi, I am XiaoYang!</h2><p className="profile-lead">视觉设计师，擅长把需求整理成<br/><em>清晰、可执行的视觉结果。</em></p><p>拥有多年视觉设计、品牌与 AI 工作流经验，擅长把复杂信息整理成清晰、可复用、可持续迭代的系统。</p><div className="experience-metrics"><div><strong>3+</strong><span>年专业经验</span></div><div><strong>500+</strong><span>内容与页面资产</span></div><div><strong>95%+</strong><span>客户满意度</span></div><div><strong>20%+</strong><span>迭代效率提升</span></div></div><a href="#contact" className="text-link">了解我的经历 <ArrowRight/></a></div></div><div className="career-path" aria-label="Career path"><p className="eyebrow">CAREER PATH / 职业路径</p><div className="career-line"><article><b>2016</b><span>视觉设计起步</span></article><article><b>2019</b><span>品牌与产品设计</span></article><article className="current"><b>2023</b><span>AI 工作流与内容系统</span></article><article><b>NOW</b><span>独立创作与合作</span></article></div></div></section>
  <section id="selected" className="home-showcase-shell jade-showcase-page" aria-label="作品与能力展示"><OrbitShowcase works={data.works}/><CapabilityShowcase/></section>
  <PersonalExtensionGallery works={data.works}/>
  <ResumePdfModule resume={data.resume}/>
  <section id="strengths" className="capabilities"><div className="strengths-head"><p className="eyebrow">个人优势</p><h2 className="section-display">CORE STRENGTHS</h2><p className="section-subtitle">让视觉、策略与执行<br/>在一个系统里协同。</p></div><div className="strengths-grid">{[['01','商业设计思维','不止于审美表达，更关注目标、平台规范与最终落地效果。'],['02','品牌视觉系统','把品牌语言、组件与内容组织成一套一致的视觉体验。'],['03','高效协作交付','明确边界、节奏与反馈，让复杂项目持续向前推进。'],['04','趋势与风格迭代','持续观察设计趋势、媒介变化与用户偏好，保持表达新鲜。']].map((x,i)=><article tabIndex={0} onMouseEnter={()=>setActiveStrength(i)} onFocus={()=>setActiveStrength(i)} className={activeStrength===i?'is-featured':''} key={x[0]}><span>{x[0]}</span><h3>{x[1]}</h3><p>{x[2]}</p>{i<2&&<img className="strength-art" src={`/strength-art-${i+1}.jpg`} alt="" aria-hidden="true"/>}{activeStrength===i&&<div className="strength-pills"><i>Strategy</i><i>Visual</i><i>AI</i></div>}{activeStrength===i&&<a href="#contact">查看合作方式 <ArrowRight size={14}/></a>}</article>)}</div></section>
  <section className="writing-preview"><div className="section-title"><div><p className="eyebrow">FIELD NOTES / 思考记录</p><h2>把思考变成可复用的认知资产。</h2></div><Link className="text-link" href="/writing">阅读全部文章 <ArrowRight/></Link></div>{data.posts.slice(0,3).map(p=><Link className="post-row" key={p.id} href={`/writing/${p.slug}`}><span>{p.category}</span><h3>{p.title}</h3><p>{p.excerpt}</p><ArrowRight/></Link>)}</section><Footer settings={{...data.settings,name:'XiaoYang'}}/>
 </main>}

function Page({children,data}:{children:React.ReactNode;data:SiteData}){return <main className="page"><Header name={data.settings.name}/><div className="page-body">{children}</div><Footer settings={data.settings}/></main>}
function WorkIndex({data}:{data:SiteData}){const [filter,setFilter]=useState('全部');const filters=['全部','Agent','Workflow','RAG','产品方法','AI Automation'];const visible=data.works.filter(x=>filter==='全部'||x.kicker.includes(filter)||x.stack.some(t=>t.includes(filter)));return <Page data={data}><header className="catalog-intro"><div><p className="eyebrow">PROJECTS CATALOG / 作品目录</p><h1>我把复杂问题，<br/><em>做成可用的产品。</em></h1></div><p>一组关于智能体、工作流、知识系统与 AI 自动化的产品设计案例。每个项目都从问题出发，经过结构化设计，最后回到真实使用。</p></header><div className="catalog-toolbar"><span>{visible.length} 个项目</span><div>{filters.map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x}</button>)}</div></div><div className="catalog-grid">{visible.map((x,i)=><WorkCard key={x.id} item={x} index={i}/>)}</div></Page>}
function WorkDetail({data,slug}:{data:SiteData;slug:string}){const x=data.works.find(w=>w.slug===slug);if(!x)return <NotFound/>;const related=data.works.filter(w=>w.id!==x.id).slice(0,2);return <Page data={data}><Link className="back" href="/work"><ArrowLeft/> 返回项目目录</Link><article className="case case-editorial"><header className="case-lead"><p className="eyebrow">CASE STUDY / {x.kicker}</p><h1>{x.title}</h1><p className="case-deck">{x.summary}</p><div className="tags">{x.stack.map(t=><span key={t}>{t}</span>)}</div></header>{x.cover_url?<img className="case-cover" src={x.cover_url} alt=""/>:<div className="case-cover cover-placeholder"><Sparkles/><span>AI PROJECT</span></div>}<div className="case-meta"><span>项目类型<br/><b>{x.kicker}</b></span><span>核心方法<br/><b>{x.stack.slice(0,2).join(' · ')}</b></span><span>交付结果<br/><b>{x.result}</b></span></div><div className="case-story">{[['01 / 背景与问题',x.problem],['02 / 产品与体验设计',x.solution],['03 / 结果与反思',x.result]].map(([a,b])=><section key={a}><p className="eyebrow">{a}</p><p>{b}</p></section>)}</div><div className="case-next"><p className="eyebrow">MORE PROJECTS / 继续浏览</p><div>{related.map(item=><Link key={item.id} href={`/work/${item.slug}`}><span>{item.kicker}</span><b>{item.title}</b><ArrowRight/></Link>)}</div></div></article></Page>}
function Writing({data}:{data:SiteData}){return <Page data={data}><header className="editorial-intro"><p className="eyebrow">BLOG SHOWCASE / 文章与思考</p><h1>把思考，变成<br/><em>可复用的认知资产。</em></h1><p>关于 AI 产品、智能体、产品方法和工作流设计的持续记录。不是追逐热点，而是把每一次实践沉淀成下一次判断。</p></header><div className="featured-post">{data.posts[0]&&<Link href={`/writing/${data.posts[0].slug}`}><div><p className="eyebrow">FEATURED NOTE / 精选文章</p><h2>{data.posts[0].title}</h2><p>{data.posts[0].excerpt}</p><span>阅读文章 <ArrowRight/></span></div>{data.posts[0].cover_url&&<img src={data.posts[0].cover_url} alt=""/>}</Link>}</div><div className="post-list editorial-post-list">{data.posts.slice(1).map((p,i)=><Link className="post-card" key={p.id} href={`/writing/${p.slug}`}><span>{String(i+2).padStart(2,'0')}</span><div><p className="eyebrow">{contentTypeNames[p.content_type]} · {p.category} · {p.published_at?.slice(0,10)}</p><h2>{p.title}</h2><p>{p.excerpt}</p></div><ArrowRight/></Link>)}</div></Page>}
function PostDetail({data,slug}:{data:SiteData;slug:string}){const p=data.posts.find(x=>x.slug===slug);if(!p)return <NotFound/>;return <Page data={data}><Link className="back" href="/writing"><ArrowLeft/> 返回全部内容</Link><article className="article"><header><p className="eyebrow">{contentTypeNames[p.content_type]} · {p.category} · {p.published_at?.slice(0,10)}</p><h1>{p.title}</h1><p>{p.excerpt}</p></header>{p.video_url?<video className="article-featured-media" controls playsInline preload="metadata" poster={p.cover_url||undefined} src={p.video_url} onError={event=>{const video=event.currentTarget;if(video.dataset.fallback)return;video.dataset.fallback='1';video.poster='/xiaoyang-card-final-4.jpg';video.removeAttribute('src');video.load()}}/>:p.cover_url?<img className="article-featured-media" src={p.cover_url} alt="" onError={event=>{const image=event.currentTarget;if(image.dataset.fallback)return;image.dataset.fallback='1';image.src='/xiaoyang-card-final-4.jpg'}}/>:null}<RichContent className="article-body" html={p.body}/></article></Page>}
function About({data}:{data:SiteData}){const r=data.resume;const email=r.email||data.settings.email||'hello@example.com';return <Page data={data}><header className="about-hero"><div><p className="eyebrow">30 秒认识我</p><h1>把复杂 AI 变得<br/><em>清晰、可靠、可交付。</em></h1></div><aside><p>{r.profile}</p><a className="text-link" href={`mailto:${email}`}>和我聊聊 <ArrowRight/></a></aside></header><section className="resume"><div><p className="eyebrow">经历 / 3 分钟深入了解</p>{r.experience.map((e,i)=><article key={i}><span>{e.period}</span><div><h3>{e.role}</h3><b>{e.company}</b><p>{e.detail}</p></div></article>)}</div><aside><p className="eyebrow">核心能力</p><div className="skill-cloud">{r.skills.map(x=><span key={x}>{x}</span>)}</div><div className="availability"><Sparkles/><p>{r.availability}</p><span>{r.location}</span></div></aside></section></Page>}
function ContactPage(){const [form,setForm]=useState({name:'',contact:'',email:'',message:''});const [state,setState]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setState('提交中…');try{await api.submitContact(form);setState('已收到，我会尽快与你联系。');setForm({name:'',contact:'',email:'',message:''})}catch(err){setState(err instanceof Error?err.message:'提交失败，请稍后再试。')}};return <main className="page contact-page"><Header name="Auria"/><div className="page-body"><header className="page-intro"><p className="eyebrow">CONTACT / 开始合作</p><h1>把一个想法，<br/><em>变成可用的系统。</em></h1><p>如果你正在做 AI 产品、智能体、工作流或自动化项目，欢迎把你的想法告诉我。</p></header><form className="contact-form" onSubmit={submit}><div className="form-grid"><Field label="姓名"><Input required value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></Field><Field label="联系方式"><Input value={form.contact} onChange={e=>setForm({...form,contact:e.target.value})} placeholder="微信、电话或 WhatsApp"/></Field><Field label="邮箱"><Input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></Field></div><Field label="你想聊什么"><Textarea required value={form.message} onChange={e=>setForm({...form,message:e.target.value})} placeholder="项目方向、当前问题、希望完成的事情……"/></Field><button className="button dark-btn" disabled={state==='提交中…'}>{state==='提交中…'?'正在提交…':'发送信息'} <ArrowRight/></button>{state&&<p className="form-status">{state}</p>}</form></div></main>}
function NotFound(){return <main className="not-found"><h1>404</h1><p>这个页面暂时不在系统中。</p><Link className="button light" href="/">返回首页</Link></main>}

type Tab='overview'|'works'|'writing'|'resume'|'avatar'|'media'|'contacts'|'settings';
const emptyWork:Partial<Work>={title:'',slug:'',kicker:'AI 产品',summary:'',problem:'',solution:'',result:'',stack:[],cover_url:'',showcase_url:'',showcase_type:'image',showcase_layout:'standard',showcase_highlight:'',showcase_cta:'查看项目',status:'draft',featured:0,sort_order:0};
const emptyPost:Partial<Post>={title:'',slug:'',category:'产品思考',excerpt:'',body:'',cover_url:'',content_type:'article',video_url:'',status:'draft',published_at:''};
function Field({label,children}:{label:string;children:React.ReactNode}){return <label className="field"><span>{label}</span>{children}</label>}
function Input(props:React.InputHTMLAttributes<HTMLInputElement>){return <input {...props}/>}
function Textarea(props:React.TextareaHTMLAttributes<HTMLTextAreaElement>){return <textarea {...props}/>}
function MediaField({label,value,onChange,media,kind='image',done}:{label:string;value?:string;onChange:(url:string)=>void;media:MediaItem[];kind?:'image'|'video'|'document';done:(message:string)=>void}){const accept=kind==='image'?'image/jpeg,image/png,image/webp,image/gif':kind==='video'?'video/mp4':'application/pdf';const choices=media.filter(item=>kind==='image'?item.content_type.startsWith('image/'):kind==='video'?item.content_type==='video/mp4':item.content_type==='application/pdf');const noun=kind==='image'?'图片':kind==='video'?'视频':'PDF';return <div className="field media-field"><span>{label}</span><div className="media-field-row"><Input value={value||''} onChange={e=>onChange(e.target.value)} placeholder={`粘贴${noun}地址，或上传/选择素材`}/><label className="mini-upload"><Upload/> 上传<input type="file" accept={accept} onChange={async e=>{const file=e.target.files?.[0];if(!file)return;try{const item=await api.upload(file);onChange(item.url);done(`${noun}上传成功`)}catch(error){done(`上传失败：${error instanceof Error?error.message:'请稍后重试。'}`)}finally{e.target.value=''}}}/></label></div>{choices.length>0&&<select value="" onChange={e=>{if(e.target.value)onChange(e.target.value)}}><option value="">从媒体库选择…</option>{choices.map(item=><option key={item.id} value={item.url}>{item.name}</option>)}</select>}{value&&(kind==='image'?<img className="media-field-preview" src={value} alt="封面预览"/>:kind==='video'?<video className="media-field-preview" src={value} controls preload="metadata"/>:<a className="document-preview" href={value} target="_blank" rel="noreferrer"><FileText/> 打开当前 PDF <ExternalLink/></a>)}</div>}

function AdminLogin({onLogin}:{onLogin:(data:AdminData)=>void}){const [email,setEmail]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');return <main className="admin-gate"><Logo/><CircleUserRound/><h1>站点管理后台</h1><p>请输入站长账号登录。</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await api.login(email,password);const data=await api.adminData();onLogin(data)}catch(err){setError(err instanceof Error?err.message:'登录失败')}finally{setBusy(false)}}}><Field label="邮箱"><Input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username" required/></Field><Field label="密码"><Input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></Field>{error&&<p className="hint">{error}</p>}<button className="button dark-btn" disabled={busy}>{busy?'正在登录…':'登录后台'}</button></form><Link className="text-link" href="/">返回网站</Link></main>}
function Admin(){const [data,setData]=useState<AdminData|null>(null),[error,setError]=useState(''),[tab,setTab]=useState<Tab>('overview'),[toast,setToast]=useState<{message:string;error:boolean}|null>(null);
  const normalizeAdminData=(value:AdminData):AdminData=>({...value,works:value.works||[],posts:value.posts||[],media:value.media||[],contacts:value.contacts||[],avatar:{...defaultAvatar,...(value.avatar||{})}});
  const refresh=()=>api.adminData().then(value=>setData(normalizeAdminData(value))).catch(e=>setError(e.message));
  const notify=(message:string,isError=false)=>{setToast({message,error:isError});setTimeout(()=>setToast(null),3600)};
  useEffect(()=>{document.title='管理后台 — XiaoYang'},[]);
  useEffect(()=>{void refresh();const rejected=(event:PromiseRejectionEvent)=>{event.preventDefault();notify(event.reason instanceof Error?event.reason.message:'操作失败，请稍后重试。',true)};window.addEventListener('unhandledrejection',rejected);return()=>window.removeEventListener('unhandledrejection',rejected)},[]);
  const done=(m:string)=>{notify(m);void refresh()};
  if(error&&/登录|后台尚未配置|401|凭据/.test(error))return <AdminLogin onLogin={next=>{setError('');setData(normalizeAdminData(next))}}/>;
  if(error)return <main className="admin-gate"><Logo/><CircleUserRound/><h1>站点管理后台</h1><p>{error}</p><Link className="button dark-btn" href="/">返回网站</Link></main>;
  if(!data)return <main className="loading"><LoaderCircle className="spin"/><span>正在打开内容后台…</span></main>;
  const tabs:[Tab,React.ReactNode,string][]=[['overview',<LayoutDashboard/>,'总览'],['works',<FolderKanban/>,'作品'],['writing',<PenLine/>,'文章'],['resume',<FileText/>,'个人简历'],['avatar',<Bot/>,'数字分身'],['media',<Image/>,'媒体库'],['contacts',<FileText/>,'联系表单'],['settings',<Settings/>,'首页设置']];
  return <main className="admin"><aside className="admin-side"><Logo/><nav>{tabs.map(([id,icon,name])=><button key={id} className={tab===id?'active':''} aria-label={name} title={name} onClick={()=>setTab(id)}>{icon}{name}</button>)}</nav><div><span>当前登录账号</span><b>{data.user.email}</b><Link href="/">查看网站 <ExternalLink/></Link><button onClick={async()=>{await api.logout();setData(null);setError('请先登录站长后台。')}}>退出登录</button></div></aside><section className="admin-main"><header><div><p className="eyebrow">PRIVATE CONTENT STUDIO / 私有内容后台</p><h1>{tabs.find(x=>x[0]===tab)?.[2]}</h1></div><Badge><span className="pulse"/> 仅站长可见</Badge></header>{tab==='overview'&&<Overview data={data} go={setTab}/>} {tab==='works'&&<WorksAdmin items={data.works} media={data.media} done={done}/>} {tab==='writing'&&<PostsAdmin items={data.posts} media={data.media} done={done}/>} {tab==='resume'&&<ResumeAdmin value={data.resume} media={data.media} done={done}/>} {tab==='avatar'&&<AvatarAdmin value={data.avatar} done={done}/>} {tab==='media'&&<MediaAdmin data={data} done={done}/>} {tab==='contacts'&&<ContactsAdmin items={data.contacts} done={done}/>} {tab==='settings'&&<SettingsAdmin value={data.settings} media={data.media} done={done}/>}</section>{toast&&<div className={`toast ${toast.error?'error':''}`}>{toast.error?<X/>:<Check/>} {toast.message}</div>}</main>
}
function Overview({data,go}:{data:AdminData;go:(x:Tab)=>void}){return <><div className="stats">{[[data.works.length,'作品'],[data.posts.length,'文章'],[data.works.filter(x=>x.status==='published').length+data.posts.filter(x=>x.status==='published').length,'已发布'],[data.media.length,'媒体文件']].map(([n,l])=><div key={String(l)}><strong>{n}</strong><span>{l}</span></div>)}</div><div className="admin-card"><div className="section-title"><div><p className="eyebrow">QUICK START / 快速操作</p><h2>持续更新你的个人品牌。</h2></div></div><div className="quick-grid"><button onClick={()=>go('works')}><Plus/> 新建作品 <ChevronRight/></button><button onClick={()=>go('writing')}><PenLine/> 发布文章 <ChevronRight/></button><button onClick={()=>go('settings')}><Settings/> 修改首页 <ChevronRight/></button></div></div></>}
function WorksAdmin({items,media,done}:{items:Work[];media:MediaItem[];done:(s:string)=>void}){
  const [editing,setEditing]=useState<Partial<Work>|null>(null);
  const save=async()=>{if(!editing)return;editing.id?await api.updateWork(editing.id,editing):await api.createWork(editing);setEditing(null);done('作品已保存')};
  const remove=async(id:string)=>{if(confirm('确定删除这个作品吗？')){await api.deleteWork(id);done('作品已删除')}};
  return <AdminCollection title="作品管理" add={()=>setEditing({...emptyWork})} button="新建作品">
    {editing&&<WorkForm value={editing} media={media} done={done} set={setEditing} close={()=>setEditing(null)} save={save}/>}<div className="admin-list">{items.map(x=><div key={x.id}>{x.showcase_type==='video'&&x.showcase_url?<video src={x.showcase_url} muted preload="metadata"/>:(x.showcase_url||x.cover_url)?<img src={x.showcase_url||x.cover_url} alt=""/>:<div className="doc-icon"><FolderKanban/></div>}<div><b>{x.title}</b><span>{x.featured?'精选 · ':''}{x.showcase_layout||'standard'} · {x.kicker}</span></div><Status status={x.status}/><button onClick={()=>setEditing(x)}>编辑</button><button className="danger" aria-label="删除" onClick={()=>remove(x.id)}><Trash2/></button></div>)}</div>
  </AdminCollection>;
}
function WorkForm({value,media,done,set,close,save}:{value:Partial<Work>;media:MediaItem[];done:(s:string)=>void;set:(x:Partial<Work>)=>void;close:()=>void;save:()=>void}){
  const f=(k:keyof Work)=>(e:React.ChangeEvent<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>)=>set({...value,[k]:e.target.value});
  return <div className="editor"><div className="editor-head"><h2>{value.id?'编辑作品':'新建作品'}</h2><button onClick={close} aria-label="关闭"><X/></button></div><div className="form-grid">
    <Field label="作品标题"><Input value={value.title||''} onChange={f('title')}/></Field><Field label="网址别名"><Input value={value.slug||''} onChange={f('slug')} placeholder="可留空自动生成"/></Field><Field label="分类标签"><Input value={value.kicker||''} onChange={f('kicker')}/></Field><Field label="发布状态"><select value={value.status} onChange={f('status')}><option value="draft">草稿</option><option value="published">已发布</option></select></Field>
    <Field label="首页版式"><select value={value.showcase_layout||'standard'} onChange={f('showcase_layout')}><option value="wide">横向主项目</option><option value="portrait">纵向项目</option><option value="standard">标准项目</option></select></Field><Field label="首页媒体类型"><select value={value.showcase_type||'image'} onChange={f('showcase_type')}><option value="image">图片</option><option value="video">视频</option></select></Field>
    <label className="toggle-field work-featured-toggle"><input type="checkbox" checked={Boolean(value.featured)} onChange={e=>set({...value,featured:e.target.checked?1:0})}/><span>设为首页精选</span></label><Field label="首页排序"><Input type="number" value={value.sort_order??0} onChange={e=>set({...value,sort_order:Number(e.target.value)||0})}/></Field>
    <MediaField label="作品封面" value={value.cover_url} onChange={cover_url=>set({...value,cover_url})} media={media} done={done}/><MediaField label="首页展示媒体" kind={value.showcase_type==='video'?'video':'image'} value={value.showcase_url} onChange={showcase_url=>set({...value,showcase_url})} media={media} done={done}/>
    <Field label="一句话介绍"><Textarea value={value.summary||''} onChange={f('summary')}/></Field><Field label="首页成果条"><Textarea value={value.showcase_highlight||''} onChange={f('showcase_highlight')} placeholder="留空时使用最终结果"/></Field><Field label="首页行动文字"><Input value={value.showcase_cta||''} onChange={f('showcase_cta')} placeholder="例如：查看项目"/></Field><Field label="遇到的问题"><Textarea value={value.problem||''} onChange={f('problem')}/></Field><Field label="我的行动"><Textarea value={value.solution||''} onChange={f('solution')}/></Field><Field label="最终结果"><Textarea value={value.result||''} onChange={f('result')}/></Field><Field label="能力标签（逗号分隔）"><Input value={value.stack?.join(', ')||''} onChange={e=>set({...value,stack:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></Field>
  </div><button className="button dark-btn" onClick={save}><Save/> 保存作品</button></div>;
}
function PostsAdmin({items,media,done}:{items:Post[];media:MediaItem[];done:(s:string)=>void}){const [editing,setEditing]=useState<Partial<Post>|null>(null);const [query,setQuery]=useState('');const [filter,setFilter]=useState<'all'|'draft'|'published'>('all');const visible=items.filter(item=>(filter==='all'||item.status===filter)&&`${item.title} ${item.category}`.toLowerCase().includes(query.toLowerCase()));const save=async(status:'draft'|'published')=>{if(!editing)return;const payload={...editing,status};editing.id?await api.updatePost(editing.id,payload):await api.createPost(payload);setEditing(null);done(status==='published'?'内容已发布':'草稿已保存')};const remove=async(id:string)=>{if(confirm('确定删除这条内容吗？')){await api.deletePost(id);done('内容已删除')}};return <AdminCollection title="内容发布中心" add={()=>setEditing({...emptyPost})} button="新建内容">{editing&&<PostForm value={editing} media={media} done={done} set={setEditing} close={()=>setEditing(null)} save={save}/>}<div className="content-filters"><label><Search/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索标题或分类"/></label><div>{(['all','draft','published'] as const).map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x==='all'?'全部':x==='draft'?'草稿':'已发布'}</button>)}</div></div><div className="admin-list content-list">{visible.map(x=><div key={x.id}>{x.cover_url?<img src={x.cover_url} alt=""/>:<div className="doc-icon">{x.content_type==='video'?<Play/>:x.content_type==='gallery'?<Image/>:<FileText/>}</div>}<div><b>{x.title}</b><span>{contentTypeNames[x.content_type]} · {x.category}</span></div><Status status={x.status}/><button onClick={()=>setEditing(x)}>编辑</button><button className="danger" aria-label="删除" onClick={()=>remove(x.id)}><Trash2/></button></div>)}</div>{visible.length===0&&<p className="empty-state">没有符合条件的内容。</p>}</AdminCollection>}
function PostForm({value,media,done,set,close,save}:{value:Partial<Post>;media:MediaItem[];done:(s:string)=>void;set:(x:Partial<Post>)=>void;close:()=>void;save:(status:'draft'|'published')=>void}){const f=(k:keyof Post)=>(e:React.ChangeEvent<HTMLInputElement|HTMLTextAreaElement|HTMLSelectElement>)=>set({...value,[k]:e.target.value});return <div className="editor post-editor"><div className="editor-head"><div><p className="eyebrow">CONTENT EDITOR / 富媒体编辑器</p><h2>{value.id?'编辑内容':'新建内容'}</h2></div><button onClick={close} aria-label="关闭"><X/></button></div><div className="form-grid"><Field label="内容标题"><Input value={value.title||''} onChange={f('title')}/></Field><Field label="网址别名"><Input value={value.slug||''} onChange={f('slug')} placeholder="可留空自动生成"/></Field><Field label="内容类型"><select value={value.content_type||'article'} onChange={f('content_type')}><option value="article">图文文章</option><option value="video">视频内容</option><option value="gallery">多图图集</option></select></Field><Field label="内容分类"><Input value={value.category||''} onChange={f('category')} placeholder="例如：AI 产品、实战复盘"/></Field><MediaField label="封面图片" value={value.cover_url} onChange={cover_url=>set({...value,cover_url})} media={media} done={done}/>{value.content_type==='video'&&<MediaField label="主视频" kind="video" value={value.video_url} onChange={video_url=>set({...value,video_url})} media={media} done={done}/>}<Field label="内容摘要"><Textarea value={value.excerpt||''} onChange={f('excerpt')} placeholder="用于列表页和分享预览，建议 60—120 字"/></Field><Field label="发布时间（可留空自动生成）"><Input type="datetime-local" value={value.published_at?.slice(0,16)||''} onChange={f('published_at')}/></Field></div><div className="body-editor-field"><span>正文内容</span><p>{value.content_type==='video'?'主视频会显示在正文上方，正文仍可继续插入图文和更多视频。':value.content_type==='gallery'?'这是富文本多图图集：可连续插入多张图片，并在图片之间添加标题、说明和视频。':'支持完整排版，也可以直接上传并插入图片或 MP4 视频。'}</p><Suspense fallback={<div className="rich-editor-loading"><LoaderCircle className="spin"/> 正在加载富文本编辑器…</div>}><RichTextEditor value={value.body||''} onChange={body=>set({...value,body})} media={media} upload={async file=>{const item=await api.upload(file);done('素材上传成功');return item;}} previewMeta={{title:value.title,excerpt:value.excerpt,category:value.category,coverUrl:value.cover_url,videoUrl:value.video_url}}/></Suspense></div><div className="editor-actions"><button className="button secondary-btn" onClick={()=>save('draft')}><Save/> 保存草稿</button><button className="button dark-btn" onClick={()=>save('published')}><Upload/> 发布内容</button></div></div>}
function AdminCollection({title,add,button,children}:{title:string;add:()=>void;button:string;children:React.ReactNode}){return <div className="admin-card"><div className="admin-card-head"><div><p className="eyebrow">CONTENT / 内容管理</p><h2>{title}</h2></div><button className="button dark-btn" onClick={add}><Plus/>{button}</button></div>{children}</div>}
function Status({status}:{status:string}){return <span className={`status ${status}`}>{status==='published'?'已发布':'草稿'}</span>}
function ResumeAdmin({value,media,done}:{value:ResumeData;media:MediaItem[];done:(x:string)=>void}){
  const [v,setV]=useState(value);
  const updateExperience=(index:number,key:keyof ResumeData['experience'][number],next:string)=>setV({...v,experience:v.experience.map((item,i)=>i===index?{...item,[key]:next}:item)});
  const updateEducation=(index:number,key:keyof ResumeData['education'][number],next:string)=>setV({...v,education:v.education.map((item,i)=>i===index?{...item,[key]:next}:item)});
  return <div className="admin-card form-page resume-editor">
    <h2>个人简介与简历</h2>
    <Field label="个人价值简介"><Textarea value={v.profile} onChange={e=>setV({...v,profile:e.target.value})}/></Field>
    <div className="form-grid">
      <Field label="当前求职 / 合作状态"><Input value={v.availability} onChange={e=>setV({...v,availability:e.target.value})}/></Field>
      <Field label="所在地区"><Input value={v.location} onChange={e=>setV({...v,location:e.target.value})}/></Field>
      <Field label="联系邮箱"><Input type="email" value={v.email} onChange={e=>setV({...v,email:e.target.value})}/></Field>
      <Field label="核心能力（逗号分隔）"><Textarea value={v.skills.join(', ')} onChange={e=>setV({...v,skills:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}/></Field>
    </div>
    <section className="resume-pdf-admin"><div className="repeater-head"><div><p className="eyebrow">PDF WINDOW / 完整简历窗口</p><h3>首页简历 PDF 模块</h3></div><label className="toggle-field"><input type="checkbox" checked={v.pdf_enabled} onChange={e=>setV({...v,pdf_enabled:e.target.checked})}/><span>在首页显示</span></label></div><p className="hint">模块显示在「精选作品」之后、「个人优势」之前。上传的 PDF 也会保存在媒体库。</p><div className="form-grid"><Field label="模块小标题"><Input value={v.pdf_kicker} onChange={e=>setV({...v,pdf_kicker:e.target.value})}/></Field><Field label="模块主标题"><Input value={v.pdf_title} onChange={e=>setV({...v,pdf_title:e.target.value})}/></Field><Field label="PDF 文件名"><Input value={v.pdf_file_name} onChange={e=>setV({...v,pdf_file_name:e.target.value})} placeholder="例如 XiaoYang-Resume.pdf"/></Field><Field label="模块说明"><Textarea value={v.pdf_description} onChange={e=>setV({...v,pdf_description:e.target.value})}/></Field></div><MediaField label="完整简历 PDF" kind="document" value={v.pdf_url} onChange={pdf_url=>setV({...v,pdf_url})} media={media} done={done}/><div className="resume-pdf-options"><label className="toggle-field"><input type="checkbox" checked={v.pdf_show_open} onChange={e=>setV({...v,pdf_show_open:e.target.checked})}/><span>显示「新窗口」按钮</span></label><label className="toggle-field"><input type="checkbox" checked={v.pdf_show_download} onChange={e=>setV({...v,pdf_show_download:e.target.checked})}/><span>显示「下载」按钮</span></label></div></section>
    <div className="repeater-head"><div><p className="eyebrow">CAREER / 职业经历</p><h3>工作经历</h3></div><button onClick={()=>setV({...v,experience:[...v.experience,{period:'',role:'',company:'',detail:''}]})}><Plus/> 添加经历</button></div>
    {v.experience.map((item,index)=><div className="repeater" key={`experience-${index}`}>
      <div className="form-grid"><Field label="时间"><Input value={item.period} onChange={e=>updateExperience(index,'period',e.target.value)}/></Field><Field label="职位"><Input value={item.role} onChange={e=>updateExperience(index,'role',e.target.value)}/></Field><Field label="公司 / 项目"><Input value={item.company} onChange={e=>updateExperience(index,'company',e.target.value)}/></Field><Field label="工作成果"><Textarea value={item.detail} onChange={e=>updateExperience(index,'detail',e.target.value)}/></Field></div>
      <button className="remove-row" onClick={()=>setV({...v,experience:v.experience.filter((_,i)=>i!==index)})}><Trash2/> 删除这条</button>
    </div>)}
    <div className="repeater-head"><div><p className="eyebrow">LEARNING / 学习经历</p><h3>教育与持续学习</h3></div><button onClick={()=>setV({...v,education:[...v.education,{period:'',title:'',place:''}]})}><Plus/> 添加教育经历</button></div>
    {v.education.map((item,index)=><div className="repeater" key={`education-${index}`}><div className="form-grid"><Field label="时间"><Input value={item.period} onChange={e=>updateEducation(index,'period',e.target.value)}/></Field><Field label="专业 / 学习方向"><Input value={item.title} onChange={e=>updateEducation(index,'title',e.target.value)}/></Field><Field label="院校 / 平台"><Input value={item.place} onChange={e=>updateEducation(index,'place',e.target.value)}/></Field></div><button className="remove-row" onClick={()=>setV({...v,education:v.education.filter((_,i)=>i!==index)})}><Trash2/> 删除这条</button></div>)}
    <button className="button dark-btn" onClick={async()=>{await api.updateResume(v);done('简历已保存')}}><Save/> 保存简历</button>
  </div>
}
function AvatarAdmin({value,done}:{value:AvatarAdminSettings;done:(x:string)=>void}){const [v,setV]=useState({...defaultAvatar,...value});const suggestions=v.suggestions.join('\n');const presets=v.presets.map(item=>`${item.question} => ${item.answer}`).join('\n');return <div className="admin-card form-page avatar-admin"><div className="repeater-head"><div><p className="eyebrow">DIGITAL AVATAR / 数字分身</p><h2>首页对话分身</h2></div><label className="toggle-field"><input type="checkbox" checked={v.enabled} onChange={e=>setV({...v,enabled:e.target.checked})}/><span>在首页显示</span></label></div><p className="hint">密钥、接口地址和模型只从服务器环境变量读取，这里不会显示或保存密钥。</p><div className="form-grid"><Field label="分身名称"><Input value={v.name} onChange={e=>setV({...v,name:e.target.value})}/></Field><Field label="英文副标题"><Input value={v.subtitle} onChange={e=>setV({...v,subtitle:e.target.value})}/></Field><Field label="欢迎语"><Textarea value={v.welcome} onChange={e=>setV({...v,welcome:e.target.value})}/></Field><Field label="输入框提示"><Input value={v.placeholder} onChange={e=>setV({...v,placeholder:e.target.value})}/></Field><Field label="推荐问题（每行一个）"><Textarea value={suggestions} onChange={e=>setV({...v,suggestions:e.target.value.split('\n').map(x=>x.trim()).filter(Boolean)})}/></Field><Field label="最长回答 Token"><Input type="number" min="100" max="2000" value={v.max_output_tokens} onChange={e=>setV({...v,max_output_tokens:Number(e.target.value)||700})}/></Field></div><Field label="回答规则 / System Prompt"><Textarea rows={7} value={v.system_prompt} onChange={e=>setV({...v,system_prompt:e.target.value})}/></Field><Field label="个人资料与知识"><Textarea rows={10} value={v.knowledge} onChange={e=>setV({...v,knowledge:e.target.value})}/></Field><Field label="固定问答（每行：问题 => 回答）"><Textarea rows={8} value={presets} onChange={e=>setV({...v,presets:e.target.value.split('\n').map(line=>{const index=line.indexOf('=>');return index<0?{question:'',answer:''}:{question:line.slice(0,index).trim(),answer:line.slice(index+2).trim()}}).filter(item=>item.question&&item.answer)})}/></Field><button className="button dark-btn" onClick={async()=>{await api.updateAvatar(v);done('数字分身设置已保存')}}><Save/> 保存数字分身设置</button></div>}
function SettingsAdmin({value,media,done}:{value:SiteSettings;media:MediaItem[];done:(x:string)=>void}){const [v,setV]=useState(value);const f=(k:keyof SiteSettings)=>(e:React.ChangeEvent<HTMLInputElement|HTMLTextAreaElement>)=>setV({...v,[k]:e.target.value});return <div className="admin-card form-page"><h2>首页与个人品牌</h2><div className="form-grid"><Field label="品牌名称"><Input value={v.name} onChange={f('name')}/></Field><Field label="个人定位"><Input value={v.role} onChange={f('role')}/></Field><Field label="主标题 — 开头"><Input value={v.hero_prefix} onChange={f('hero_prefix')}/></Field><Field label="主标题 — 强调内容"><Input value={v.hero_emphasis} onChange={f('hero_emphasis')}/></Field><Field label="主标题 — 结尾"><Input value={v.hero_suffix} onChange={f('hero_suffix')}/></Field><MediaField label="首页背景视频" kind="video" value={v.hero_video_url} onChange={hero_video_url=>setV({...v,hero_video_url})} media={media} done={done}/><Field label="首页个人介绍"><Textarea value={v.hero_description} onChange={f('hero_description')}/></Field><Field label="联系邮箱"><Input value={v.email} onChange={f('email')}/></Field><Field label="所在地区"><Input value={v.location} onChange={f('location')}/></Field></div><button className="button dark-btn" onClick={async()=>{await api.updateSettings(v);done('首页设置已保存')}}><Save/> 保存首页设置</button></div>}
function MediaAdmin({data,done}:{data:AdminData;done:(x:string)=>void}){const [busy,setBusy]=useState(0);const [uploadDone,setUploadDone]=useState(0);const [filter,setFilter]=useState<'all'|'image'|'video'|'document'>('all');const visible=data.media.filter(item=>filter==='all'||(filter==='image'&&item.content_type.startsWith('image/'))||(filter==='video'&&item.content_type.startsWith('video/'))||(filter==='document'&&!item.content_type.startsWith('image/')&&!item.content_type.startsWith('video/')));return <div className="admin-card"><div className="admin-card-head"><div><p className="eyebrow">ASSET LIBRARY / 素材管理</p><h2>媒体库</h2><p className="hint">支持 JPG、PNG、WebP、GIF、MP4 和 PDF，单文件不超过 25 MB。</p></div><label className="button dark-btn upload"><Upload/> 批量上传<input type="file" multiple accept="image/jpeg,image/png,image/webp,image/gif,video/mp4,application/pdf" onChange={async e=>{const files=Array.from(e.target.files||[]);if(!files.length)return;setBusy(files.length);setUploadDone(0);let success=0;const failed:string[]=[];try{for(const file of files){try{await api.upload(file);success++}catch(error){failed.push(`${file.name}：${error instanceof Error?error.message:'上传失败'}`)}finally{setUploadDone(value=>value+1)}}done(failed.length?`上传完成：成功 ${success} 个，失败 ${failed.length} 个。${failed[0]}`:`已上传 ${success} 个文件`)}finally{setBusy(0);e.target.value='';}}}/></label></div><div className="media-filter-bar">{(['all','image','video','document'] as const).map(x=><button key={x} className={filter===x?'active':''} onClick={()=>setFilter(x)}>{x==='all'?'全部':x==='image'?'图片':x==='video'?'视频':'文档'}</button>)}</div>{busy>0&&<div className="upload-progress" role="status" aria-live="polite"><div><LoaderCircle className="spin"/> <span>正在上传 {uploadDone} / {busy} 个文件</span></div><span className="upload-progress-track"><span style={{'--upload-progress':`${busy?uploadDone/busy*100:0}%`} as React.CSSProperties}/></span></div>}<div className="media-grid">{visible.map(x=><div key={x.id}>{x.content_type.startsWith('image/')?<img src={x.url} alt=""/>:x.content_type.startsWith('video/')?<video src={x.url} controls preload="metadata"/>:<div className="file-thumb"><FileText/></div>}<b>{x.name}</b><span>{x.content_type.replace('application/','').replace('image/','').replace('video/','').toUpperCase()} · {(x.size/1024).toFixed(0)} KB</span><div className="media-actions"><button onClick={()=>{void navigator.clipboard.writeText(x.url);done('素材网址已复制')}}>复制网址</button><button className="danger" onClick={async()=>{if(confirm(`确定删除 ${x.name} 吗？`)){await api.deleteMedia(x.id);done('素材已删除')}}}><Trash2/> 删除</button></div></div>)}</div>{visible.length===0&&<p className="empty-state">这个分类还没有素材。</p>}</div>}
function ContactsAdmin({items,done}:{items:Contact[];done:(x:string)=>void}){return <div className="admin-card"><div className="admin-card-head"><div><p className="eyebrow">INBOX / 联系收件箱</p><h2>访客联系</h2><p className="hint">表单提交会先保存到网站，再尝试推送主飞书机器人。</p></div></div>{items.length===0?<p className="empty-state">暂时没有新的联系。</p>:<div className="contact-list">{items.map(item=><article key={item.id}><div><b>{item.name}</b><span>{item.created_at}</span></div><p>{item.contact||'—'} · {item.email||'未填写邮箱'}</p><p>{item.message}</p><button className="danger" onClick={async()=>{if(confirm('确定删除这条联系记录吗？')){await api.deleteContact(item.id);done('联系记录已删除')}}}><Trash2/> 删除</button></article>)}</div>}</div>}

export default function App(){const page=new URLSearchParams(window.location.search).get('page');const path=page?`/${page.replace(/^\/+/, '')}`:window.location.pathname;const [data,setData]=useState<SiteData>(fallback),[loading,setLoading]=useState(true);useEffect(()=>{if(path==='/admin')return;api.publicData().then(setData).catch(console.error).finally(()=>setLoading(false))},[path]);useEffect(()=>{if(path==='/admin'||loading)return;const items=Array.from(document.querySelectorAll<HTMLElement>('.portfolio-site .portfolio-work-tile, .portfolio-site .work-showcase-card, .portfolio-site .open-source-card, .portfolio-site .portfolio-feature-grid > *, .portfolio-site .portfolio-capability-grid > *, .portfolio-site .portfolio-note-list > *, .portfolio-site .writing-feature, .portfolio-site .writing-list>a, .portfolio-site .case-heading, .portfolio-site .case-visual-evidence, .portfolio-site .case-facts, .portfolio-site .case-sections section, .portfolio-site .case-related, .portfolio-site .about-grid, .portfolio-site .about-experience>div, .portfolio-site .about-skills, .portfolio-site .contact-editorial label, .portfolio-site .contact-note, .portfolio-site .portfolio-footer, .home-cyber .experience-layout > *, .home-cyber .career-line > *, .home-cyber .work-card, .home-cyber .strengths-grid > article, .home-cyber .post-row, .home-cyber .career-path, .home-cyber footer .footer-contact-grid, .home-cyber footer .footer-bottom'));items.forEach((el,i)=>{el.classList.add('reveal-item');el.style.setProperty('--reveal-delay',`${Math.min(i%5,4)*70}ms`)});const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}}),{threshold:.12,rootMargin:'0px 0px -8%'});items.forEach(el=>observer.observe(el));return()=>observer.disconnect()},[path,loading]);const route=useMemo(()=>path.split('/').filter(Boolean),[path]);if(path==='/admin')return <Admin/>;if(loading)return <SiteLoading/>;if(path==='/')return <Home data={data}/>;if(path==='/work')return <WorkPage data={data}/>;if(path==='/open-source')return <OpenSourcePage settings={data.settings}/>;if(route[0]==='work'&&route[1])return <DetailPage data={data} slug={route[1]}/>;if(path==='/writing')return <WritingPage data={data}/>;if(route[0]==='writing'&&route[1])return <PostPage data={data} slug={route[1]}/>;if(path==='/about')return <AboutPage data={data}/>;if(path==='/contact')return <PortfolioContactPage settings={data.settings}/>;return <NotFoundPage/>}
